//#region src/internal/getAnnouncement.ts
/** Returns an announcement message when the remaining count is low. */
const getAnnouncement = (count, maxCount, translationIds, t) => {
	if (typeof maxCount === "undefined") return null;
	const remaining = maxCount - count;
	if (remaining <= 10 && remaining > 0) return t(translationIds.remaining, {
		count: remaining,
		maxCount
	});
	if (remaining <= 0) return t(translationIds.maxReached, {
		count: maxCount,
		maxCount
	});
	return null;
};
//#endregion
export { getAnnouncement };
